def count_pairs(nums, k):
    n = len(nums)
    count = 0
    # Loop through all possible pairs i < j
    for i in range(n):
        for j in range(i + 1, n):
            # Check nums[i] == nums[j] AND (i × j) divisible by k
            if nums[i] == nums[j]:
                if (i * j) % k == 0:
                    count += 1
    return count
